    required this.title,
    required this.order,
  });

  @override
  int get hashCode => root.hashCode ^ title.hashCode ^ order.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WorkspaceProject &&
          runtimeType == other.runtimeType &&
          root == other.root &&
          title == other.title &&
          order == other.order;
}
